insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('SG:accountant','2026-08-11',0,0,0,0,10,0,0,0,4,14,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps the broad non-tax Accountant role directly to 24111 Accountant excluding tax accountant; Auditor 24112 and Tax accountant 24113 remain separate.','entry_level_basis','Accounting and accountancy degrees provide direct preparation; five approved Singapore accountancy programmes are retained as direct study pathways.','qualification_note','ACRA states that general accounting work does not require Public Accountant registration. Public accountancy services such as auditing and reporting on financial statements are separately reserved to registered Public Accountants.','market_scope','No exact current shortage, vacancy, salary or growth series has yet been normalised into SG v1.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:financial-analyst','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps Financial analyst directly to 24131 and separates financial risk/compliance, portfolio management and financial advisory occupations.','entry_level_basis','Finance, quantitative finance, economics, accountancy and related analytical degrees provide relevant preparation; fourteen approved programmes are related study pathways.','qualification_note','There is no universal statutory occupational registration for the broad Financial Analyst role. Regulated financial-services activities and representatives can carry separate activity-specific requirements.','market_scope','Programme availability is not treated as demand evidence and all market components remain unscored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:business-analyst','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','For non-ICT Business Analyst, SSOC 2024 directly lists Business analyst as an example under 24212 Business consultant. ICT business analyst remains separately classified at 25112 and is excluded.','entry_level_basis','Business analytics and business-technology study provide relevant preparation; six approved programmes are related pathways rather than professional credentials.','qualification_note','There is no universal statutory occupational registration for non-ICT Business Analysts.','market_scope','The clean classification anchor does not imply an exact current labour-market series in CampCareer SG v1.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:supply-chain-analyst','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 does not provide one five-digit occupation titled Supply chain analyst. Analytical improvement work spans 24212 Business consultant, which explicitly includes Supply chain consultant, and 33461 Logistics/Production planner, which includes Logistics solutions analyst.','entry_level_basis','Supply-chain, maritime, international trading and digital supply-chain study provide relevant preparation; four approved programmes are related pathways.','qualification_note','There is no universal statutory occupational registration for Supply Chain Analysts.','market_scope','The two reference occupations are not combined into a fabricated exact salary, vacancy or shortage series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:human-resources-specialist','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','The canonical HR Specialist spans SSOC 24231 Human resource consultant and 24233 Personnel/Human resource officer. 24231 explicitly includes compensation and benefits specialists and talent acquisition specialists, while 24233 covers generalist HR development and personnel work.','entry_level_basis','Human-resource management and HR consulting degrees provide direct subject preparation; two approved programmes are retained as direct study pathways.','qualification_note','There is no universal statutory occupational registration for Human Resources Specialists. Employment-law, recruitment-agency or industrial-relations activities can have separate organisational or role-specific rules.','market_scope','Multiple HR sub-scopes are preserved without manufacturing one exact market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:marketing-specialist','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','The canonical Marketing Specialist spans SSOC 24312 Market research professional, 24313 Marketing strategy/planning professional and 24314 Digital marketing professional rather than one five-digit occupation.','entry_level_basis','Marketing, business and digital-media study provide relevant preparation; three approved programmes are related pathways.','qualification_note','There is no universal statutory occupational registration for Marketing Specialists.','market_scope','Research, strategy and digital marketing classifications are kept distinct and are not merged into an unsupported occupation-level market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:auditor','2026-08-11',0,0,0,0,10,0,0,0,3,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps Auditor accounting directly to 24112 and explicitly includes both External auditor and Internal auditor.','entry_level_basis','Accountancy degrees provide a common academic route; five approved programmes are related pathways because degree completion alone does not confer statutory public-audit authority.','qualification_note','ACRA requires Public Accountant registration to provide public accountancy services such as auditing and reporting on financial statements. Because SSOC 24112 also includes Internal auditor, the broad canonical Auditor role is not treated as universally requiring every worker to be a registered PA.','market_scope','Statutory audit regulation is not converted into labour-demand credit.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:project-manager','2026-08-11',0,0,0,0,8,0,0,0,5,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','Singapore does not have one cross-industry five-digit SSOC occupation for generic Project Manager. 24213 Business/Financial project management professional is retained as the closest non-sector business-project reference, while construction, ICT, logistics and other sector project managers remain in their own classifications.','entry_level_basis','Project-management, business and engineering study can support entry, but dedicated project-manager roles commonly depend on prior domain and delivery experience; four approved programmes are related pathways.','qualification_note','There is no universal statutory occupational registration for cross-industry Project Managers. Sector-specific regulated responsibilities remain separate.','market_scope','The 24213 reference is not presented as an exact generic Project Manager labour-market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11')
